@Controller()
export class HeroesController implements OnModuleInit {
  constructor(
    @Inject('HERO_SERVICE') private readonly client: ClientKafkaProxy,
  ) {}

  async onModuleInit() {
    this.client.subscribeToResponseOf('hero.kill.dragon');
    await this.client.connect();
  }

  killDragon(@Payload() message: KillDragonMessage) {
    return this.client.send('hero.kill.dragon', message);
  }
}

@EventPattern('user.created')
async handleUserCreated(
  @Payload() data: any,
  @Ctx() context: KafkaContext,
) {
  // 业务逻辑
  const { offset } = context.getMessage();
  const partition = context.getPartition();
  const topic = context.getTopic();
  const consumer = context.getConsumer();

  // 提交下一个待消费的偏移量
  await consumer.commitOffsets([
    { topic, partition, offset: (Number(offset) + 1).toString() },
  ]);
}
